-- ConnectionCyber - M14: ledger de importacao tenant-scoped.
-- Armazena somente hashes, metricas e referencias; nunca backup, credencial ou payload bruto.
begin;

create table public.erp_import_manifests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,idempotency_key text not null check(length(idempotency_key)between 16 and 200),source_type text not null check(source_type in('sqlserver_backup','sqlserver_readonly','csv_export','json_export')),source_sha256 text not null check(source_sha256~'^[a-f0-9]{64}$'),schema_version text not null check(schema_version~'^legacy-[a-z0-9.-]+$'),captured_at timestamptz not null,immutable boolean not null default true,metadata jsonb not null default '{}'::jsonb,status text not null default'registered'check(status in('registered','validated','blocked','retired')),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,source_sha256,schema_version),unique(tenant_id,id),check(immutable),check(jsonb_typeof(metadata)='object'and metadata::text!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|connection_string|source_path)"[[:space:]]*:'));
create table public.erp_import_mappings(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,source_schema_version text not null,target_contract_version text not null,domain text not null check(domain in('customers','suppliers','employees','products','stock','sales','cash','receivables','payables','fiscal_metadata')),mapping_hash text not null check(mapping_hash~'^[a-f0-9]{64}$'),rules jsonb not null default '{}'::jsonb,status text not null default'draft'check(status in('draft','validated','retired')),created_at timestamptz not null default now(),constraint uq_import_mapping_context unique(tenant_id,source_schema_version,target_contract_version,domain),unique(tenant_id,id),check(jsonb_typeof(rules)='object'and rules::text!~*'"(password|senha|secret|token|credential|private_key|service_role|pfx|p12|csc|connection_string|source_path)"[[:space:]]*:'));
create table public.erp_import_jobs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,manifest_id uuid not null,idempotency_key text not null check(length(idempotency_key)between 16 and 200),status text not null default'planned'check(status in('planned','validated','running','completed','failed','rolled_back')),expected_count bigint not null check(expected_count>=0),expected_amount_cents bigint not null check(expected_amount_cents>=0),started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,manifest_id)references public.erp_import_manifests(tenant_id,id)on delete restrict,check(finished_at is null or started_at is not null));
create table public.erp_import_batches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,job_id uuid not null,domain text not null check(domain in('customers','suppliers','employees','products','stock','sales','cash','receivables','payables','fiscal_metadata')),sequence integer not null check(sequence>0),batch_hash text not null check(batch_hash~'^[a-f0-9]{64}$'),expected_count integer not null check(expected_count between 1 and 1000),expected_amount_cents bigint not null check(expected_amount_cents>=0),actual_count integer,actual_amount_cents bigint,status text not null default'planned'check(status in('planned','validated','reconciled','blocked','applied','rolled_back')),created_at timestamptz not null default now(),unique(tenant_id,job_id,domain,sequence),unique(tenant_id,batch_hash),unique(tenant_id,id),foreign key(tenant_id,job_id)references public.erp_import_jobs(tenant_id,id)on delete restrict,check(actual_count is null or actual_count>=0),check(actual_amount_cents is null or actual_amount_cents>=0));
create table public.erp_import_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,batch_id uuid not null,canonical_key text not null check(canonical_key~'^canonical:[a-z0-9:-]{8,200}$'),source_key_hash text not null check(source_key_hash~'^[a-f0-9]{64}$'),payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),source_amount_cents bigint not null default 0 check(source_amount_cents>=0),target_ref uuid,status text not null default'planned'check(status in('planned','imported','duplicate','rejected','rolled_back')),created_at timestamptz not null default now(),unique(tenant_id,batch_id,canonical_key),unique(tenant_id,batch_id,source_key_hash),unique(tenant_id,id),foreign key(tenant_id,batch_id)references public.erp_import_batches(tenant_id,id)on delete restrict);
create table public.erp_import_rejections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,batch_id uuid not null,item_id uuid,error_code text not null check(length(error_code)between 3 and 80),detail_hash text not null check(detail_hash~'^[a-f0-9]{64}$'),status text not null default'open'check(status in('open','resolved','waived')),created_at timestamptz not null default now(),resolved_at timestamptz,unique(tenant_id,batch_id,item_id,error_code),unique(tenant_id,id),foreign key(tenant_id,batch_id)references public.erp_import_batches(tenant_id,id)on delete restrict,foreign key(tenant_id,item_id)references public.erp_import_items(tenant_id,id)on delete restrict,check((status='open'and resolved_at is null)or(status<>'open'and resolved_at is not null)));
create table public.erp_import_reconciliations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,job_id uuid not null,batch_id uuid not null,expected_count bigint not null,actual_count bigint not null,expected_amount_cents bigint not null,actual_amount_cents bigint not null,balanced boolean generated always as(expected_count=actual_count and expected_amount_cents=actual_amount_cents)stored,evidence_hash text not null check(evidence_hash~'^[a-f0-9]{64}$'),created_at timestamptz not null default now(),unique(tenant_id,batch_id),unique(tenant_id,id),foreign key(tenant_id,job_id)references public.erp_import_jobs(tenant_id,id)on delete restrict,foreign key(tenant_id,batch_id)references public.erp_import_batches(tenant_id,id)on delete restrict);

insert into public.erp_permissions(key,name,description,category)values('import.read','Consultar importacoes','Consulta manifestos, lotes e reconciliacoes do tenant.','Importacao'),('import.execute','Executar importacao','Autoriza solicitacao de jobs server-side com AAL2.','Importacao'),('import.audit','Auditar importacao','Consulta evidencias e rejeicoes do tenant.','Importacao')on conflict(key)do update set name=excluded.name,description=excluded.description,category=excluded.category,active=true;

create or replace function public.erp_register_import_manifest(p_tenant_id uuid,p_idempotency_key text,p_source_type text,p_source_sha256 text,p_schema_version text,p_captured_at timestamptz,p_metadata jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare v_existing record;v_id uuid;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if length(btrim(p_idempotency_key))not between 16 and 200 or p_source_type not in('sqlserver_backup','sqlserver_readonly','csv_export','json_export')or p_source_sha256!~'^[a-f0-9]{64}$'or p_schema_version!~'^legacy-[a-z0-9.-]+$'or p_captured_at is null or jsonb_typeof(p_metadata)<>'object'then raise exception 'invalid manifest';end if;if p_metadata::text~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|connection_string|source_path)"[[:space:]]*:'then raise exception 'secret or source path forbidden';end if;select id,source_type,source_sha256,schema_version,captured_at,metadata into v_existing from public.erp_import_manifests where tenant_id=p_tenant_id and idempotency_key=btrim(p_idempotency_key);if v_existing.id is not null then if v_existing.source_type<>p_source_type or v_existing.source_sha256<>p_source_sha256 or v_existing.schema_version<>p_schema_version or v_existing.captured_at<>p_captured_at or v_existing.metadata<>p_metadata then raise exception 'manifest idempotency conflict';end if;return v_existing.id;end if;insert into public.erp_import_manifests(tenant_id,idempotency_key,source_type,source_sha256,schema_version,captured_at,metadata)values(p_tenant_id,btrim(p_idempotency_key),p_source_type,p_source_sha256,p_schema_version,p_captured_at,p_metadata)returning id into v_id;return v_id;end$$;
create or replace function public.erp_open_import_job(p_tenant_id uuid,p_manifest_id uuid,p_idempotency_key text,p_expected_count bigint,p_expected_amount_cents bigint)returns uuid language plpgsql security definer set search_path=''as $$declare v_existing record;v_id uuid;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if length(btrim(p_idempotency_key))not between 16 and 200 or p_expected_count<0 or p_expected_amount_cents<0 then raise exception 'invalid job';end if;select id,manifest_id,expected_count,expected_amount_cents into v_existing from public.erp_import_jobs where tenant_id=p_tenant_id and idempotency_key=btrim(p_idempotency_key);if v_existing.id is not null then if v_existing.manifest_id<>p_manifest_id or v_existing.expected_count<>p_expected_count or v_existing.expected_amount_cents<>p_expected_amount_cents then raise exception 'job idempotency conflict';end if;return v_existing.id;end if;insert into public.erp_import_jobs(tenant_id,manifest_id,idempotency_key,expected_count,expected_amount_cents)values(p_tenant_id,p_manifest_id,btrim(p_idempotency_key),p_expected_count,p_expected_amount_cents)returning id into v_id;return v_id;end$$;
create or replace function public.erp_open_import_batch(p_tenant_id uuid,p_job_id uuid,p_domain text,p_sequence integer,p_batch_hash text,p_expected_count integer,p_expected_amount_cents bigint)returns uuid language plpgsql security definer set search_path=''as $$declare v_existing record;v_id uuid;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if p_domain not in('customers','suppliers','employees','products','stock','sales','cash','receivables','payables','fiscal_metadata')or p_sequence<1 or p_batch_hash!~'^[a-f0-9]{64}$'or p_expected_count not between 1 and 1000 or p_expected_amount_cents<0 then raise exception 'invalid batch';end if;select id,batch_hash,expected_count,expected_amount_cents into v_existing from public.erp_import_batches where tenant_id=p_tenant_id and job_id=p_job_id and domain=p_domain and sequence=p_sequence;if v_existing.id is not null then if v_existing.batch_hash<>p_batch_hash or v_existing.expected_count<>p_expected_count or v_existing.expected_amount_cents<>p_expected_amount_cents then raise exception 'batch idempotency conflict';end if;return v_existing.id;end if;insert into public.erp_import_batches(tenant_id,job_id,domain,sequence,batch_hash,expected_count,expected_amount_cents)values(p_tenant_id,p_job_id,p_domain,p_sequence,p_batch_hash,p_expected_count,p_expected_amount_cents)returning id into v_id;return v_id;end$$;
create or replace function public.erp_record_import_item(p_tenant_id uuid,p_batch_id uuid,p_canonical_key text,p_source_key_hash text,p_payload_hash text,p_source_amount_cents bigint)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_hash text;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if p_canonical_key!~'^canonical:[a-z0-9:-]{8,200}$'or p_source_key_hash!~'^[a-f0-9]{64}$'or p_payload_hash!~'^[a-f0-9]{64}$'or p_source_amount_cents<0 then raise exception 'invalid item';end if;select id,payload_hash into v_id,v_hash from public.erp_import_items where tenant_id=p_tenant_id and batch_id=p_batch_id and canonical_key=p_canonical_key;if v_id is not null then if v_hash<>p_payload_hash then raise exception 'canonical key conflict';end if;return v_id;end if;insert into public.erp_import_items(tenant_id,batch_id,canonical_key,source_key_hash,payload_hash,source_amount_cents)values(p_tenant_id,p_batch_id,p_canonical_key,p_source_key_hash,p_payload_hash,p_source_amount_cents)returning id into v_id;return v_id;end$$;
create or replace function public.erp_finalize_import_batch(p_tenant_id uuid,p_batch_id uuid,p_evidence_hash text)returns uuid language plpgsql security definer set search_path=''as $$declare v_batch record;v_count bigint;v_amount bigint;v_id uuid;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if p_evidence_hash!~'^[a-f0-9]{64}$'then raise exception 'invalid evidence';end if;select * into v_batch from public.erp_import_batches where tenant_id=p_tenant_id and id=p_batch_id for update;if v_batch.id is null then raise exception 'batch not found';end if;if v_batch.status='reconciled'then select id into v_id from public.erp_import_reconciliations where tenant_id=p_tenant_id and batch_id=p_batch_id;return v_id;end if;select count(*),coalesce(sum(source_amount_cents),0)into v_count,v_amount from public.erp_import_items where tenant_id=p_tenant_id and batch_id=p_batch_id;if v_count<>v_batch.expected_count or v_amount<>v_batch.expected_amount_cents then update public.erp_import_batches set actual_count=v_count,actual_amount_cents=v_amount,status='blocked'where tenant_id=p_tenant_id and id=p_batch_id;raise exception 'reconciliation mismatch';end if;insert into public.erp_import_reconciliations(tenant_id,job_id,batch_id,expected_count,actual_count,expected_amount_cents,actual_amount_cents,evidence_hash)values(p_tenant_id,v_batch.job_id,p_batch_id,v_batch.expected_count,v_count,v_batch.expected_amount_cents,v_amount,p_evidence_hash)on conflict(tenant_id,batch_id)do update set evidence_hash=excluded.evidence_hash returning id into v_id;update public.erp_import_batches set actual_count=v_count,actual_amount_cents=v_amount,status='reconciled'where tenant_id=p_tenant_id and id=p_batch_id;return v_id;end$$;

do $$declare t text;begin foreach t in array array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
create policy erp_import_manifests_select on public.erp_import_manifests for select to authenticated using(erp_security.has_permission(tenant_id,'import.read')or erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_mappings_select on public.erp_import_mappings for select to authenticated using(erp_security.has_permission(tenant_id,'import.read')or erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_jobs_select on public.erp_import_jobs for select to authenticated using(erp_security.has_permission(tenant_id,'import.read')or erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_batches_select on public.erp_import_batches for select to authenticated using(erp_security.has_permission(tenant_id,'import.read')or erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_items_select on public.erp_import_items for select to authenticated using(erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_rejections_select on public.erp_import_rejections for select to authenticated using(erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());
create policy erp_import_reconciliations_select on public.erp_import_reconciliations for select to authenticated using(erp_security.has_permission(tenant_id,'import.read')or erp_security.has_permission(tenant_id,'import.audit')or public.is_platform_staff());

revoke execute on function public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb),public.erp_open_import_job(uuid,uuid,text,bigint,bigint),public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint),public.erp_record_import_item(uuid,uuid,text,text,text,bigint),public.erp_finalize_import_batch(uuid,uuid,text)from public,anon,authenticated,service_role;
grant execute on function public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb),public.erp_open_import_job(uuid,uuid,text,bigint,bigint),public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint),public.erp_record_import_item(uuid,uuid,text,text,text,bigint),public.erp_finalize_import_batch(uuid,uuid,text)to service_role;
commit;
